-- Prevent permanent deletion when financial, moderation, report, support, referral or storage history must be retained.
create or replace function private.admin_user_delete_preflight(p_user_id uuid)
returns jsonb language plpgsql stable security definer set search_path=''
as $function$
declare v_fk record; v_count bigint; v_fk_blockers jsonb:='[]'::jsonb; v_financial jsonb:='[]'::jsonb; v_retained jsonb:='[]'::jsonb; v_item record;
begin
 if auth.uid() is null or not private.spike_is_owner() then raise exception 'SPIKE owner access required' using errcode='42501'; end if;
 if p_user_id is null or not exists(select 1 from auth.users u where u.id=p_user_id and u.deleted_at is null) then raise exception 'User not found'; end if;
 for v_fk in select c.conrelid::regclass::text table_name,string_agg(format('%I = $1',a.attname),' and ') predicate from pg_constraint c join lateral unnest(c.conkey,c.confkey) k(attnum,confattnum) on true join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum join pg_attribute ta on ta.attrelid=c.confrelid and ta.attnum=k.confattnum where c.contype='f' and c.confdeltype in ('a','r') and c.confrelid in ('auth.users'::regclass,'public.profiles'::regclass) and ta.attname='id' group by c.oid,c.conrelid loop
  execute format('select count(*) from %s where %s',v_fk.table_name,v_fk.predicate) into v_count using p_user_id;
  if v_count>0 then v_fk_blockers:=v_fk_blockers||jsonb_build_array(jsonb_build_object('table',v_fk.table_name,'rows',v_count)); end if;
 end loop;
 for v_item in select * from (values ('public.wallets','user_id','balance > 0'),('public.coin_ledger','user_id','true'),('public.coin_orders','user_id','true'),('public.coin_transactions','user_id','true'),('public.gem_transactions','user_id','true'),('public.gift_history','sender_id','true'),('public.gift_history','receiver_id','true'),('public.spike_room_gift_transactions','sender_id','true'),('public.spike_room_gift_transactions','receiver_id','true'),('public.spike_live_audio_gift_transactions','sender_id','true'),('public.spike_live_audio_gift_transactions','room_owner_id','true'),('public.spike_live_audio_gift_transactions','broadcaster_id','true'),('public.spike_creator_earnings_ledger','user_id','true'),('public.spike_creator_wallets','user_id','true'),('public.spike_creator_withdrawals','user_id','true'),('public.spike_creator_payout_accounts','user_id','true'),('public.spike_payout_accounts','user_id','true'),('public.monthly_payouts','user_id','true'),('public.spike_revenue','user_id','true'),('public.spike_room_message_rewards','sender_id','true'),('public.spike_room_message_rewards','receiver_id','true'),('public.spike_coin_source_balances','user_id','paid_balance > 0 or bonus_balance > 0'),('private.spike_verified_subscriptions','user_id','true')) x(table_name,column_name,condition) loop
  if to_regclass(v_item.table_name) is not null then execute format('select count(*) from %s where %I=$1 and (%s)',v_item.table_name,v_item.column_name,v_item.condition) into v_count using p_user_id; if v_count>0 then v_financial:=v_financial||jsonb_build_array(jsonb_build_object('table',v_item.table_name,'rows',v_count)); end if; end if;
 end loop;
 for v_item in select * from (values ('public.profile_reports','reported_user_id'),('public.profile_reports','reporter_id'),('public.spike_support_cases','user_id'),('public.spike_room_reports','reporter_id'),('public.spike_room_message_reports','reporter_id'),('public.feed_reports','reporter_id'),('public.referrals','referrer_id'),('public.referrals','referred_id'),('private.spike_referral_attributions','inviter_id'),('private.spike_referral_attributions','invitee_id'),('private.spike_referral_point_ledger','user_id')) x(table_name,column_name) loop
  if to_regclass(v_item.table_name) is not null then execute format('select count(*) from %s where %I=$1',v_item.table_name,v_item.column_name) into v_count using p_user_id; if v_count>0 then v_retained:=v_retained||jsonb_build_array(jsonb_build_object('table',v_item.table_name,'rows',v_count)); end if; end if;
 end loop;
 if to_regclass('public.spike_room_reports') is not null then select count(*) into v_count from public.spike_room_reports rr join public.spike_rooms r on r.id=rr.room_id where r.host_id=p_user_id; if v_count>0 then v_retained:=v_retained||jsonb_build_array(jsonb_build_object('table','public.spike_room_reports_about_hosted_rooms','rows',v_count)); end if; end if;
 if to_regclass('public.spike_room_message_reports') is not null then select count(*) into v_count from public.spike_room_message_reports mr join public.spike_room_messages m on m.id=mr.message_id where m.sender_id=p_user_id; if v_count>0 then v_retained:=v_retained||jsonb_build_array(jsonb_build_object('table','public.spike_room_message_reports_about_user','rows',v_count)); end if; end if;
 if to_regclass('storage.objects') is not null then execute 'select count(*) from storage.objects where owner=$1 or owner_id=$1::text' into v_count using p_user_id; if v_count>0 then v_retained:=v_retained||jsonb_build_array(jsonb_build_object('table','storage.objects','rows',v_count)); end if; end if;
 return jsonb_build_object('user_id',p_user_id,'allowed',jsonb_array_length(v_fk_blockers)=0 and jsonb_array_length(v_financial)=0 and jsonb_array_length(v_retained)=0,'foreign_key_blockers',v_fk_blockers,'financial_history',v_financial,'retained_history',v_retained,'message',case when jsonb_array_length(v_financial)>0 then 'Deletion is blocked because this account has financial or gift history that must be retained.' when jsonb_array_length(v_retained)>0 then 'Deletion is blocked because this account has report, support, referral or stored-file history that must be retained.' when jsonb_array_length(v_fk_blockers)>0 then 'Deletion is blocked by linked records that must be resolved or retained.' else 'Preflight passed. Permanent deletion will remove the account and remaining cascading personal records.' end);
end;
$function$;
